// 1. Recolectamos el texto con una extracción más robusta
const listaEscenarios = items.map(item => {
  const json = item.json;

  // CASO A: Estructura compleja de Gemini (según tu captura image_b2c14c.png)
  // content -> parts -> [0] -> text
  if (json.content && json.content.parts && json.content.parts[0] && json.content.parts[0].text) {
    return json.content.parts[0].text;
  }

  // CASO B: Estructura simple (si viene directo)
  return json.text || json.output || json.content;
})
.filter(texto => texto) // Elimina nulos o undefined
.map(texto => {
  // SEGURIDAD: Convertimos a String antes de hacer trim()
  // Esto evita el error si llega un número o un objeto por error
  return String(texto).trim(); 
});

// 2. Unimos todo con un separador Markdown claro
const contenidoUnido = listaEscenarios.join('\n\n---\n\n');

// 3. Creamos el documento final con encabezado y fecha
const fecha = new Date().toLocaleDateString('es-ES');
const documentoFinal = `# Reporte de Tablas\n> Generado el: ${fecha}\n\n${contenidoUnido}`;

// 4. Devolvemos el paquete para Azure DevOps
return [{
  json: {
    contenido_wiki: documentoFinal,
    page_path: "CriteriosS1", 
  }
}];

// 1. Obtenemos el contenido
const content = items[0].json.content;

if (!content) {
  return [{ json: { error: "El nodo HTTP no trajo contenido." } }];
}

// 2. ESTRATEGIA FLEXIBLE: DIVIDIR POR CABECERAS DE HU
const splitRegex = /(?:\n|^)(?=(?:#{1,6}\s*|[\*_]*)\s*(?:Nro\.?)?\s*HU\s*-?\s*\d+)/i;

const bloques = content.split(splitRegex);
const historias = [];

bloques.forEach(bloque => {
  const texto = bloque.trim();

  // A. INTENTAR EXTRAER EL ID Y TÍTULO
  const headerMatch = texto.match(/HU\s*-?\s*(\d+)[\s\S]*?Título\s*:?\s*([^\n\r]+)/i);

  if (headerMatch) {
    const idNum = headerMatch[1];
    const tituloLimpio = headerMatch[2].replace(/[\*_]/g, '').trim();

    // B. BUSCAR LA DESCRIPCIÓN
    let descripcion = "Descripción no detectada";
    const narrativaMatch = texto.match(/(COMO\s+[\s\S]+?QUIERO\s+[\s\S]+?PARA\s+[\s\S]+?)(?=\.|\||\n|$)/i);

    if (narrativaMatch) {
       descripcion = narrativaMatch[1].replace(/\|/g, '').trim(); 
    } else {
       const tablaMatch = texto.match(/Historia de Usuario\s*\|\s*([^|\r\n]+)/i);
       if (tablaMatch) descripcion = tablaMatch[1].trim();
    }

    // --- C. EXTRAER FRAMES (AQUÍ ESTÁ LA CORRECCIÓN) ---
    const frames = [];
    const sectionFramesMatch = texto.match(/(?:Frame|Prototipo)[\s\S]*?(?=(?:Observaciones|Nota|###|$))/i);

    if (sectionFramesMatch) {
      const lineasFrames = sectionFramesMatch[0].split('\n');
      lineasFrames.forEach(linea => {
        // Verifica si la línea parece un item de lista (*, -, +, v)
        if (linea.match(/^\s*[-*+v]\.?\s*/i)) {
             // Limpia los caracteres especiales del inicio
             const nombreLimpio = linea.replace(/^\s*[-*+vV\.0-9]*\s*/, '').trim();

             // VALIDACIÓN NUEVA: Solo agregamos si quedó texto real (no vacío)
             if (nombreLimpio.length > 0 && nombreLimpio.toLowerCase() !== "empty") {
                 frames.push(nombreLimpio);
             }
        }
      });
    }

    // D. OBSERVACIONES
    let observaciones = "Ninguna";
    const obsMatch = texto.match(/(?:Observaciones|Nota)[\s\S]*?:([\s\S]*)/i);
    if (obsMatch) {
      observaciones = obsMatch[1].trim();
    }

    historias.push({
      json: {
        id: `HU-${idNum}`,
        titulo: tituloLimpio,
        descripcion: descripcion,
        observaciones: observaciones,
        frames: frames
      }
    });
  }
});

// 3. RESULTADO
if (historias.length === 0) {
    return [{ 
        json: { 
            warning: "Sigue sin detectar historias.",
            texto_inicio: content.substring(0, 500) 
        } 
    }];
}

return historias;

const itemsProcesados = [];

// Recorremos cada Historia de Usuario que llegó
for (const item of items) {
  const json = item.json;

  // CORRECCIÓN AQUÍ:
  // Filtramos para asegurarnos de que solo pasen textos que NO estén vacíos
  const frames = (json.frames || []).filter(f => f && f.trim() !== "");

  // Si la HU tiene frames válidos, creamos un item individual por cada uno
  if (frames.length > 0) {
    frames.forEach(frameNombre => {
      itemsProcesados.push({
        json: {
          id_hu: json.id,
          titulo_hu: json.titulo,
          descripcion: json.descripcion,
          observaciones: json.observaciones,
          nombre_imagen_buscar: frameNombre // Aquí irá el nombre limpio
        }
      });
    });
  } else {
    // Si realmente NO tiene frames (o todos eran vacíos), pasamos este aviso
    // O puedes eliminar este 'else' si prefieres que no salga nada en la tabla
    itemsProcesados.push({
      json: {
        id_hu: json.id,
        titulo_hu: json.titulo,
        descripcion: json.descripcion,
        observaciones: json.observaciones,
        nombre_imagen_buscar: "Sin Frames"
      }
    });
  }
}

return itemsProcesados;

// 1. Obtenemos TODOS los datos de texto
const datosTexto = $('Code in JavaScript6').all();

const itemsFinales = [];

// --- MAPA DE AGRUPACIÓN (Igual que antes) ---
const mapaHUs = new Map();

datosTexto.forEach(item => {
  const data = item.json;
  if (data.nombre_imagen_buscar) {
    const nombreLimpio = data.nombre_imagen_buscar.trim();
    if (!mapaHUs.has(nombreLimpio)) {
      mapaHUs.set(nombreLimpio, []);
    }
    mapaHUs.get(nombreLimpio).push(data);
  }
});

// --- NUEVO: CONTROL DE DUPLICADOS ---
// Usamos esto para anotar qué imágenes ya "atendimos"
const imagenesProcesadas = new Set();

// 2. Recorremos las imágenes de Drive
for (const itemImagen of items) {
  const driveData = itemImagen.json; 
  const binaryData = itemImagen.binary;

  // Limpieza del nombre
  const nombreArchivoSinExt = driveData.name.replace(/\.[^/.]+$/, "").trim();

  // --- FILTRO ANTI-REPETICIÓN ---
  // Si ya procesamos una imagen con este nombre, saltamos a la siguiente.
  if (imagenesProcesadas.has(nombreArchivoSinExt)) {
    continue; 
  }

  // Si es nueva, la buscamos en el mapa
  const listaHUsCoincidentes = mapaHUs.get(nombreArchivoSinExt);

  if (listaHUsCoincidentes && listaHUsCoincidentes.length > 0) {

    // Marcamos esta imagen como "YA USADA" para que no se repita
    imagenesProcesadas.add(nombreArchivoSinExt);

    // Generamos los items (HU-13, HU-14, etc.)
    for (const huData of listaHUsCoincidentes) {
      itemsFinales.push({
        json: {
          id_hu: huData.id_hu,
          titulo: huData.titulo_hu,
          descripcion: huData.descripcion,
          observaciones: huData.observaciones,

          archivo_nombre_original: driveData.name,
          archivo_id: driveData.id
        },
        binary: binaryData
      });
    }
  }
}

return itemsFinales;

const grupos = {};

// 1. Recorremos todos los items sueltos
for (const item of items) {
  const json = item.json;

  // N8N maneja los binarios de forma particular. 
  // A veces viene como 'data', a veces como el nombre del archivo. 
  // Asumiremos que viene en la propiedad por defecto que suele ser 'data' o la primera llave disponible.
  const binaryKey = Object.keys(item.binary)[0]; 
  const binary = item.binary[binaryKey];

  const idHu = json.id_hu;

  // 2. Si es la primera vez que vemos esta HU, la inicializamos
  if (!grupos[idHu]) {
    grupos[idHu] = {
      json: {
        id_hu: idHu,
        titulo: json.titulo,
        descripcion: json.descripcion,
        observaciones: json.observaciones,
        // Inicializamos el array
        frames_info: [] 
      },
      binary: {}
    };
  }

  // 3. CORRECCIÓN AQUÍ: Usamos los nombres correctos que vienen del nodo anterior
  grupos[idHu].json.frames_info.push({
    // Antes tenías json.nombre_frame (incorrecto)
    nombre: json.archivo_nombre_original, 
    // Antes tenías json.archivo_drive_id (incorrecto)
    archivo_id: json.archivo_id        
  });

  // 4. Guardamos la imagen binaria con un nombre único para que no se sobrescriban
  const indice = Object.keys(grupos[idHu].binary).length;

  // Esto crea propiedades: data_0, data_1, data_2...
  grupos[idHu].binary[`data_${indice}`] = binary;
}

// 5. Devolvemos el array limpio
return Object.values(grupos);

const content = items[0].json.content || "";

// 1. PRIMERO LIMPIAMOS: Quitamos los asteriscos (**) y saltos HTML para que el texto quede puro
// Esto soluciona el problema de que no encontrara los números antes.
const textoLimpio = content
  .replace(/\*\*/g, "") 
  .replace(/<br\s*\/?>/gi, "\n")
  .trim();

// 2. EXTRACCIÓN (Ahora sí funcionará porque el texto está limpio)
const razonMatch = textoLimpio.match(/Razon:\s*([\s\S]*?)(?=(?:Total de Nodos|Pantallas|###|$))/i);
const nodosMatch = textoLimpio.match(/Total de Nodos:\s*(\d+)/i);
const pantallasMatch = textoLimpio.match(/Pantallas:\s*(\d+)/i);

const razon = razonMatch ? razonMatch[1].trim() : "No especificada";
const nodos = nodosMatch ? nodosMatch[1] : "N/A";
const pantallas = pantallasMatch ? pantallasMatch[1] : "N/A";

// 3. UNIFICACIÓN: Creamos un solo bloque de texto formateado
const bloqueFinal = `
=== CONTEXTO DEL MAPA DE NAVEGACIÓN ===
> Resumen de actualización:
- Motivo: ${razon}
- Métricas: ${nodos} nodos y ${pantallas} pantallas involucradas.

> Detalle Completo:
${textoLimpio}
`.trim();

// 4. Salida en una sola variable
return [{
  json: {
    mapa_consolidado: bloqueFinal 
  }
}];
